      <section class="grid ke-kpi-grid">${kpi('Dossiers en cours', number(inProgress.length), `${number(data.imports.length)} dossier${data.imports.length === 1 ? '' : 's'} au total`, 'ship')}${kpi('Valeur factures', money(invoiceValue), 'Contre-valeur MAD enregistrée', 'invoice')}${kpi('Coûts accessoires', money(accessoryCosts), invoiceValue ? `${number(accessoryCosts / invoiceValue * 100)} % des factures` : 'Aucune facture valorisée', 'chart', accessoryCosts ? 'warning' : 'neutral')}${kpi('Documents rattachés', number(documentCount), 'Pièces présentes dans les dossiers', 'file')}</section>
