    const actorsToday = new Set(todayEvents.map(item => item.actorUserId || item.actorDisplayName).filter(Boolean)).size, hashCount = rawAudit.filter(item => item.hash).length, latest = rawAudit.map(item => item.occurredAt).filter(Boolean).sort().at(-1);
