    const rows = data.bankLines.map(item => `<tr data-enterprise-row data-status="${esc(item.status)}" data-amount="${Math.abs(Number(item.amount || 0))}"><td><input class="ke-row-check" type="checkbox" aria-label="Sélectionner ${esc(item.id)}" data-record="${esc(item.id)}"></td><td>${date(item.date)}</td><td><strong>${esc(item.label)}</strong><small>${esc(item.id)} · ${esc(item.account)}</small></td><td class="amount ${Number(item.amount) < 0 ? 'negative' : 'ke-positive-text'}">${Number(item.amount) > 0 ? '+' : '−'} ${money(Math.abs(item.amount))}</td><td><div class="ke-match"><span class="ref">${esc(item.suggestion)}</span>${item.confidence ? `<small>${Number(item.confidence)} % de confiance</small>` : '<small>Recherche manuelle requise</small>'}</div></td><td>${item.confidence ? `<div class="ke-confidence"><i style="width:${Number(item.confidence)}%"></i></div>` : '—'}</td><td>${status(item.status)}</td><td>${rowMenu(item.id, 'bank-line')}</td></tr>`).join('');
