  function exportTable(root, page) {
    const table = root.querySelector('.ke-table');
    if (!table) { notify('Aucun tableau disponible à exporter.', 'error'); return; }
    const lines = [...table.querySelectorAll('tr')].filter(row => row.hidden === false || !row.hidden).map(row => [...row.querySelectorAll('th,td')].map(cell => `"${cell.textContent.trim().replaceAll('"', '""')}"`).join(';'));
    const blob = new Blob(['\ufeff' + lines.join('\n')], { type: 'text/csv;charset=utf-8' }), url = URL.createObjectURL(blob), anchor = document.createElement('a');
    anchor.href = url; anchor.download = `kay-one-${page}-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); notify('Export CSV généré.');
  }

  function paginate(root, requestedPage = 1) {
    const panel = root.querySelector('.ke-pagination')?.closest('.ke-table-panel');
    if (!panel) return;
    const rows = [...panel.querySelectorAll('[data-enterprise-row]')];
    const eligible = rows.filter(row => row.dataset.filterHidden !== 'true');
    const pageSize = 10, pageCount = Math.max(1, Math.ceil(eligible.length / pageSize));
    let page = requestedPage;
    const current = Number(panel.dataset.currentPage || 1);
    if (requestedPage === 'previous') page = current - 1;
    if (requestedPage === 'next') page = current + 1;
    page = Math.max(1, Math.min(pageCount, Number(page) || 1));
    panel.dataset.currentPage = String(page);
    rows.forEach(row => { row.hidden = row.dataset.filterHidden === 'true'; });
    eligible.forEach((row, index) => { row.hidden = index < (page - 1) * pageSize || index >= page * pageSize; });
    panel.querySelectorAll('.page-button[data-page-number]').forEach(button => button.classList.toggle('active', Number(button.dataset.pageNumber) === page));
    const first = eligible.length ? (page - 1) * pageSize + 1 : 0, last = Math.min(page * pageSize, eligible.length);
    const count = panel.querySelector('[data-role="enterprise-count"]');
    if (count) count.textContent = `Affichage ${first}–${last} sur ${eligible.length}`;
  }

  function applyFilters(root) {
    const query = (root.querySelector('[data-role="enterprise-search"]')?.value || '').trim().toLocaleLowerCase('fr');
    const amountMin = Number(root.querySelector('[data-filter="amount-min"]')?.value || 0);
    const start = root.querySelector('[data-filter="date-start"]')?.value || '';
    const end = root.querySelector('[data-filter="date-end"]')?.value || '';
    const textFilters = [...root.querySelectorAll('select[data-filter]')].filter(select => !['company'].includes(select.dataset.filter) && select.value).map(select => select.value.toLocaleLowerCase('fr'));
    const companyFilter = (root.querySelector('[data-filter="company"]')?.value || '').toLocaleLowerCase('fr');
    root.querySelectorAll('[data-enterprise-row]').forEach(row => {
      const text = row.textContent.toLocaleLowerCase('fr'), rowCompany = (row.dataset.company || text).toLocaleLowerCase('fr'), rowDate = row.dataset.date || '', rowAmount = Number(row.dataset.amount || 0);
      const show = (!query || text.includes(query)) && textFilters.every(value => text.includes(value)) && (!companyFilter || rowCompany.includes(companyFilter)) && (!amountMin || rowAmount >= amountMin) && (!start || !rowDate || rowDate >= start) && (!end || !rowDate || rowDate <= end);
      row.dataset.filterHidden = String(!show);
    });
    paginate(root, 1);
  }

