      const items = dues.filter(item => open(item) && /debt|payable|dette|fourn/i.test(String(item.kind)) && item.dueDate && new Date(item.dueDate) <= limit), total = sum(items, item => read(item, 'outstandingMad', 'outstanding'));
      const partiesText = items.slice().sort((a, b) => numeric(b.outstandingMad) - numeric(a.outstandingMad)).slice(0, 3).map(item => { const party = partyById.get(String(item.partyId)); return `${esc(read(party, 'name', 'internalCode') || 'Tiers non renseigné')} (${money(read(item, 'outstandingMad', 'outstanding'))})`; });
      return result(`${number(items.length)} échéance${items.length === 1 ? '' : 's'} fournisseur sont dues au plus tard sous 15 jours, pour <strong>${money(total)}</strong>${partiesText.length ? `. Principales lignes : ${partiesText.join(', ')}.` : '.'}`, items.map(item => item.operationId));
