      if (action.startsWith('create-') || action.startsWith('confirm-') || action === 'set-user-password') { const form = root.querySelector('.ke-modal-form'); if (form && !form.reportValidity()) return; const payload = Object.fromEntries([...form?.querySelectorAll('input[name],select[name],textarea[name]') || []].map(input => [input.dataset.label || input.name, input.value])); emit(send, action, payload); root.querySelector('.ke-modal-layer')?.remove(); notify('Demande d’enregistrement transmise au moteur.'); return; }
      if (action === 'select-client' || action === 'select-supplier') { updateEntitySelection(root, data, action.split('-')[1], record); return; }
      if (action === 'switch-detail-tab') { button.parentElement.querySelectorAll('.tab').forEach(item => item.classList.remove('active')); button.classList.add('active'); const body = root.querySelector('[data-role="detail-tab-body"]'); if (body) body.innerHTML = `<div class="ke-tab-placeholder">${svg('file')}<strong>${esc(button.dataset.tab)}</strong><p>Les données liées conservent la traçabilité vers l’opération et le document d’origine.</p>${actionButton('open-linked-records', 'Afficher les éléments liés', 'secondary', 'arrow')}</div>`; return; }
      if (action === 'open-operation') { const operationId = button.dataset.operationId || data.operations.find(item => String(item.id || item.reference) === String(record))?.operationId; if (!operationId) { notify('Identifiant technique de l’opération indisponible.', 'error'); return; } const source = Array.isArray(data.raw?.operations) ? data.raw.operations.find(item => String(item.id) === String(operationId)) : null; emit(send, 'operation-trace', { id: operationId, reference: record }); openModal(root, `Opération ${record || operationId}`, `<div class="ke-record-preview"><span>${svg('link')}</span><div><strong>Traçabilité demandée au Transaction Engine</strong><p>La chaîne documentaire et financière est chargée depuis l’identifiant technique de l’opération.</p><dl><dt>Référence</dt><dd>${esc(read(source, 'reference') || record || '—')}</dd><dt>Identifiant</dt><dd>${esc(operationId)}</dd><dt>Statut enregistré</dt><dd>${esc(read(source, 'status') || '—')}</dd><dt>Montant MAD</dt><dd>${source ? money(read(source, 'amountMad', 'totalMad')) : '—'}</dd></dl></div></div>`, 'confirm-enterprise-modal', 'Fermer'); return; }
