      if (action === 'generate-commitments') { notify('Génération des engagements demandée au moteur.'); emit(send, action, { asOfDate: new Date().toISOString().slice(0, 10) }); return; }
      if (action === 'recalculate-import') { const total = [...root.querySelectorAll('[data-import-cost]')].reduce((sum, input) => sum + Number(input.value || 0), 0); const output = root.querySelector('[data-role="import-total"]'); if (output) output.textContent = money(total); notify('Coût d’acquisition recalculé.'); return; }
      if (action === 'save-import-costing') { const costs = Object.fromEntries([...root.querySelectorAll('[data-import-cost]')].map(input => [input.dataset.importCost, Number(input.value || 0)])), importFileId = button.dataset.record || root.querySelector('.ke-costing-card')?.dataset.importRecord; emit(send, action, { importFileId, ...costs }); notify('Validation du coût envoyée au moteur.'); return; }
      if (action === 'select-import') { const selected = data.imports.find(item => String(item.id) === String(record)), card = root.querySelector('.ke-costing-card'); root.querySelectorAll('[data-action="select-import"]').forEach(item => item.innerHTML = svg(item.dataset.record === record ? 'check' : 'arrow')); if (selected && card) { card.dataset.importRecord = selected.entityId || selected.id; const subtitle = card.querySelector('.panel-head p'); if (subtitle) subtitle.textContent = `${selected.id} · ventilation modifiable`; card.querySelectorAll('[data-import-cost]').forEach(input => { input.value = numeric(selected[input.dataset.importCost]); }); const totalOutput = card.querySelector('[data-role="import-total"]'); if (totalOutput) totalOutput.textContent = money(importTotal(selected)); const save = card.querySelector('[data-action="save-import-costing"]'); if (save) save.dataset.record = selected.entityId || selected.id; } notify(`Dossier ${record} sélectionné.`); return; }
