      if (action === 'report-dimension') { button.parentElement.querySelectorAll('.tab').forEach(item => item.classList.remove('active')); button.classList.add('active'); const body = root.querySelector('[data-role="profitability-body"]'); if (body) body.innerHTML = reportingDimensionRows(data, button.dataset.dimension); return; }
      if (action === 'verify-audit-integrity') { notify('Vérification d’intégrité demandée au moteur.'); emit(send, action); return; }
      if (action === 'reconcile-selected') { const checked = [...root.querySelectorAll('.ke-row-check:checked')]; if (!checked.length) { notify('Sélectionnez au moins une ligne bancaire.', 'error'); return; } notify(`Rapprochement de ${checked.length} ligne${checked.length > 1 ? 's' : ''} demandé au moteur.`); emit(send, action, { ids: checked.map(box => box.dataset.record) }); return; }
