      if (action === 'check-certificate-balance') { const select = root.querySelector('[data-role="certificate-client"]'), option = select?.selectedOptions[0], amount = Number(root.querySelector('[data-role="certificate-amount"]')?.value || 0), available = Number(option?.dataset.available || 0), output = root.querySelector('[data-role="certificate-result"]'); if (!select?.value) { notify('Sélectionnez un certificat.', 'error'); return; } if (!amount) { notify('Saisissez un montant valide.', 'error'); return; } const today = new Date(data.generatedAt || Date.now()), active = /valid|active|actif/i.test(String(option.dataset.status)) && (!option.dataset.start || new Date(option.dataset.start) <= today) && (!option.dataset.end || new Date(option.dataset.end) >= today), enough = active && available >= amount; if (output) { output.className = `ke-certificate-result ${enough ? 'success' : 'error'}`; output.innerHTML = enough ? `${svg('check')}<span><strong>Contrôle local positif</strong>Solde après facture : ${money(available - amount)}. Validation envoyée au moteur.</span>` : !active ? `${svg('alert')}<span><strong>Certificat non actif à la date du snapshot</strong>Une nouvelle attestation peut être requise.</span>` : `${svg('alert')}<span><strong>Solde insuffisant de ${money(amount - available)}</strong>La facture ne peut pas être totalement exonérée.</span>`; } emit(send, action, { certificateId: select.value, amount }); return; }
